package com.smartsociety.platform.notification; import org.springframework.beans.factory.annotation.Value; import org.springframework.mail.SimpleMailMessage; import org.springframework.mail.javamail.JavaMailSender; import org.springframework.stereotype.Service;
@Service public class EmailService {private final JavaMailSender sender;private final String from;public EmailService(JavaMailSender s,@Value("${app.notifications.from}")String f){sender=s;from=f;}public void send(String to,String subject,String body){var m=new SimpleMailMessage();m.setFrom(from);m.setTo(to);m.setSubject(subject);m.setText(body);sender.send(m);} }
